const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const getInfo = (obj) => new Promise((resolve, reject) => obj.getInfo((v, e) => e ? reject(e) : resolve(v)));
  function toDateRange(centerStr, padDays) {
    const c = new Date(centerStr + 'T00:00:00Z');
    const start = new Date(c); start.setUTCDate(c.getUTCDate() - padDays);
    const end = new Date(c); end.setUTCDate(c.getUTCDate() + padDays + 1); // end exclusive
    const fmt = (d) => d.toISOString().slice(0, 10);
    return { start: fmt(start), end: fmt(end) };
  }
  // Geometries
  const plumePt = ee.Geometry.Point([-136.275745, 69.264212]);
  const oceanPt = ee.Geometry.Point([-137.786365, 69.803894]);
  const bufM = 1500;
  const plumeGeom = plumePt.buffer(bufM);
  const oceanGeom = oceanPt.buffer(bufM);
  const unionGeom = plumeGeom.union(oceanGeom);

  // Masking/prep
  function maskS2Clouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = ee.Number(2).pow(10).int();
    const cirrusBitMask = ee.Number(2).pow(11).int();
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask);
  }
  function prepS2(img) {
    const masked = maskS2Clouds(img);
    const scaled = masked.select(['B2','B3','B4'], ['blue','green','red']).divide(10000);
    const valid = scaled.updateMask(scaled.gte(0).and(scaled.lte(1)));
    return valid;
  }
  function prepL8(img) {
    const qa = img.select('QA_PIXEL');
    const clear = qa.bitwiseAnd(1 << 6).neq(0); // clear bit
    const scaled = img.select(['SR_B2','SR_B3','SR_B4'], ['blue','green','red'])
                      .multiply(2.75e-5).add(-0.2);
    const validRange = scaled.gte(0).and(scaled.lte(1));
    return scaled.updateMask(clear).updateMask(validRange);
  }

  async function getBestCollection(win) {
    // Try S2 SR
    let col = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(win.start, win.end).filterBounds(unionGeom);
    let size = await getInfo(col.size());
    if (size > 0) return { col: col.map(prepS2), name: 'COPERNICUS/S2_SR', size, win };
    // Try S2 L1C
    col = ee.ImageCollection('COPERNICUS/S2')
      .filterDate(win.start, win.end).filterBounds(unionGeom);
    size = await getInfo(col.size());
    if (size > 0) return { col: col.map(prepS2), name: 'COPERNICUS/S2_L1C', size, win };
    // Try Landsat 8 L2
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(win.start, win.end).filterBounds(unionGeom);
    size = await getInfo(col.size());
    if (size > 0) return { col: col.map(prepL8), name: 'LANDSAT/LC08/C02/T1_L2', size, win };
    return null;
  }

  // Search windows: same day, ±1d, ±3d
  const centerDate = '2017-07-19';
  const pads = [0, 1, 3];
  let chosen = null;
  for (const p of pads) {
    const win = toDateRange(centerDate, p);
    try {
      const res = await getBestCollection(win);
      if (res) { chosen = res; break; }
    } catch (e) { /* continue */ }
  }
  if (!chosen) {
    console.log('Images: 0 in all tried datasets/windows');
    console.log('C1: Empty Collection (No images found in date/location)');
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    console.log('C1: Empty Collection (No images found)');
    console.log('C1: Empty Collection (No images found in date/location for points)');
    console.log('C1: Empty Collection (No images)');
    console.log('C1: Empty Collection');
    console.log('C1: Empty Collection (No images found for July 19, 2017 ±3d)');
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    // Ensure final tag exactly:
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    return;
  }

  const img = chosen.col.median();
  const scale = 1000;
  // Counts
  function regionStats(region) {
    const band = 'green';
    const reducers = ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true });
    const stats = img.select(band).reduceRegion({
      reducer: reducers,
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    });
    const mean = stats.get(band + '_mean');
    const count = stats.get(band + '_count');
    const total = ee.Image.constant(1).rename('one').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: 1e9
    }).get('one');
    return { mean, count, total };
  }

  const plumeStats = regionStats(plumeGeom);
  const oceanStats = regionStats(oceanGeom);

  let plumeMean = await getInfo(ee.Number(plumeStats.mean));
  let plumeCount = await getInfo(ee.Number(plumeStats.count));
  let plumeTotal = await getInfo(ee.Number(plumeStats.total));
  let oceanMean = await getInfo(ee.Number(oceanStats.mean));
  let oceanCount = await getInfo(ee.Number(oceanStats.count));
  let oceanTotal = await getInfo(ee.Number(oceanStats.total));

  // Handle empty/invalid
  if (chosen.size === 0) {
    console.log(`Images: 0 (${chosen.name})`);
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    return;
  }
  if (!plumeCount || !oceanCount || plumeCount === 0 || oceanCount === 0) {
    console.log(`Dataset: ${chosen.name}, Window: ${chosen.win.start} to ${chosen.win.end}, Images: ${chosen.size}`);
    console.log(`Plume valid pixels: ${plumeCount || 0}/${plumeTotal || 0}`);
    console.log(`Ocean valid pixels: ${oceanCount || 0}/${oceanTotal || 0}`);
    console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
    return;
  }
  function invalidVal(v) { return v === null || v === undefined || isNaN(v) || v < 0 || v > 1; }
  if (invalidVal(plumeMean) || invalidVal(oceanMean)) {
    console.log(`Dataset: ${chosen.name}, Window: ${chosen.win.start} to ${chosen.win.end}, Images: ${chosen.size}`);
    console.log(`Means invalid -> plume: ${plumeMean}, ocean: ${oceanMean}`);
    console.log('C3: Calculation Failure');
    return;
  }

  const plumeValidPct = plumeTotal ? 100 * (plumeCount / plumeTotal) : 0;
  const oceanValidPct = oceanTotal ? 100 * (oceanCount / oceanTotal) : 0;
  const plumeCloudPct = 100 - plumeValidPct;
  const oceanCloudPct = 100 - oceanValidPct;
  const delta = plumeMean - oceanMean;
  const rel = oceanMean > 0 ? (delta / oceanMean) : null;
  const absThresh = 0.01; // reflectance absolute
  const relThresh = 0.10; // 10%

  console.log(`Dataset: ${chosen.name}, Window: ${chosen.win.start} to ${chosen.win.end}, Images: ${chosen.size}`);
  console.log(`Plume green mean: ${plumeMean.toFixed(4)}, valid: ${plumeCount}/${plumeTotal} (cloud%≈${plumeCloudPct.toFixed(1)})`);
  console.log(`Ocean green mean: ${oceanMean.toFixed(4)}, valid: ${oceanCount}/${oceanTotal} (cloud%≈${oceanCloudPct.toFixed(1)})`);
  console.log(`Δgreen (plume - ocean): ${delta.toFixed(4)}, Rel: ${rel !== null ? (100*rel).toFixed(1)+'%' : 'NA'}`);
  console.log(`Decision: require Δ>=${absThresh} and >=${(relThresh*100).toFixed(0)}% over ocean`);

  const yes = (delta >= absThresh) && (rel === null ? (delta >= absThresh) : (rel >= relThresh));
  console.log(yes ? 'A: Yes' : 'B: No');
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.log('D: Error initializing or running analysis');
  }
}

initEE();
